WorkflowProcessEvent.eventDescription:
function servicetask78(attempt, message) {
    /**
     * AUTHOR: ENOS DESENVOLVEDOR FLUIG/FULL STACK 
     * CRIADO EM: 29/05/2026
     * PROPOSITO: FATURAR OS MOVIMENTOS DE VENDAS DO TIPO 2.1.02 , CRIAR MOVIMENTO 2.2.01 E GERAR O RELACIONAMENTO ENTRE ELES DENTRO DO RM 
    */



    var codColigada = hAPI.getCardValue("CodColigada");
    var idMov = hAPI.getCardValue("idmovContratos");
    var codFilial = hAPI.getCardValue("filial");
    var today = new java.text.SimpleDateFormat("yyyy-MM-dd").format(new java.util.Date());

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");

    try {

        /* 
        AQUI VAI ACONTECER A MÁGICA DA INTEGRACAO 
        1 - ServiceManager.getService("wsProcess")- > PRIMEIRO É NECESSÁRIO PEGAR O SERVICO QUE SERA RESPONSAVEL PELA INTEGRACAO DENTRO DO SEU FLUIG , EM PAIENL DE CONTROLE - SERVICOS 
        2 - instantiate() - > O SERVICO RESPOSAVEL POR INTEGRACOES MAIS COMPLEXAS DENTRO DO FLUIG É O WSPROCESS, TAMBÉM EXISTE O WSDATASERVER POREM ELE SERVE PARA CRUD MAIS SIMPLES, ALTERAR, EXCLUIR MOVIMENTOS, REALIZAR UPDATES ETCC
            COMO NESSE CASO É UMA OPERAÇÃO COMPLEXA QUE ENVOLVE RELACIONAMENTOS, FATURAMENTO, GERAÇÃO , TRANSFERENCIA DE DADOS ENTRE OS MOVIMENTOS ETC.. O WSPROCESS EXECUTA ISSO PERFEITAMENTE. 
        3 - IRÁ INSTANCIAR ESSE SERVICO , FAZER UMA ESPÉCIA DE CÓPIA DA CLASSE WSPROCESS (servico.instantiate("com.totvs.WsProcess"))
        4 - getRMIwsProcess() -> TEM ACESSO AOS METODOS DA CLASSE INTANCIADA 
        5 - properties -> INFORMACOES PARA AUTORIZACAO DO USO DO SERVICO DENTRO DO SERVIDOR DO RM, PRINCIPALMENTE O USUARIO E SENHA 
            E, INDISCUTIVELMENTE, UM TIMEOUT BOM, POIS, ISSO PODE IMPEDIR A EXECUSAO DA ATIVIDADE.
        6- getCustomClient() - > PASSAR AS INFORMACOES DE AUTORIZACOES E OS METODOS DA CLASSE INTANCIADA 
        7- executeWithParams() - > Metodo para faturar movimentos , passando o server name e o corpo XML -> executeWithParams("MovFaturamentoProc", xmlParams)

        */
        var servico = ServiceManager.getService("wsProcess");
        var instancia = servico.instantiate("com.totvs.WsProcess");
        var ws = instancia.getRMIwsProcess();
        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);

        log.info("### Servico OK, executando faturamento IDMOV=" + idMov);

        var xmlParams =
            '<MovFaturamentoProcParams>' +
            '<movCopiaFatPar>' +
            '<CodColigada>' + codColigada + '</CodColigada>' +
            '<CodSistema>T</CodSistema>' +
            '<CodTmvDestino>2.2.01</CodTmvDestino>' +
            '<CodTmvOrigem>2.1.02</CodTmvOrigem>' +
            '<CodUsuario>fluig</CodUsuario>' +
            '<GrupoFaturamento></GrupoFaturamento>' +
            '<IdExercicioFiscal>3</IdExercicioFiscal>' +
            '<IdMov>' +
            '<int>' + idMov + '</int>' +
            '</IdMov>' +
            '<TipoFaturamento>0</TipoFaturamento>' +
            '<dataBase>' + today + '</dataBase>' +
            '<dataEmissao/>' +
            '<dataSaida/>' +
            '<efeitoPedidoFatAutomatico>1</efeitoPedidoFatAutomatico>' +
            '<listaMovItemFatAutomatico/>' +
            '<numeroMov></numeroMov>' +
            '<realizaBaixaPedido>true</realizaBaixaPedido>' +
            '</movCopiaFatPar>' +
            '</MovFaturamentoProcParams>';

        var resp = authService.executeWithParams("MovFaturamentoProc", xmlParams);


    } catch (e) {
        log.error("### Erro: " + e);
        throw e;
    }



}


function getConstante(param) {
    var aConstraint = [];
    aConstraint.push(DatasetFactory.createConstraint('id', param, param, ConstraintType.MUST));
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

function servicetask87(attempt, message) {

    var codColigada = hAPI.getCardValue("CodColigada");
    var idmov       = hAPI.getCardValue("idmov2");
    var codFilial   = hAPI.getCardValue("filial") || "1";

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm   = getConstante("rm_senha");

    log.info("[G12-AjustarTributos] Iniciando - CODCOLIGADA=" + codColigada + " IDMOV=" + idmov);

    var tributosFormulario = {};
    var i = 1;

    while (true) {
        var sufixo  = "___" + i;
        var codtrbN = hAPI.getCardValue("impostos_selecao" + sufixo);

        if (codtrbN == null || codtrbN == "" || codtrbN == "null" || codtrbN == undefined) break;

        var valorN = hAPI.getCardValue("valorImposto" + sufixo);
        var aliqN  = hAPI.getCardValue("aliquota"     + sufixo);
        var baseN  = hAPI.getCardValue("baseCalculo"  + sufixo);

        tributosFormulario[String(codtrbN).trim()] = {
            valor:       valorN ? String(valorN).replace(",", ".") : "0.0000",
            aliquota:    aliqN  ? String(aliqN).replace(",",  ".") : "0.0000",
            basecalculo: baseN  ? String(baseN).replace(",",  ".") : "0.0000"
        };

        log.info("[G12-AjustarTributos] Tributo do formulario: " + String(codtrbN).trim() + " = " + JSON.stringify(tributosFormulario[String(codtrbN).trim()]));

        i++;
        if (i > 50) break;
    }

    log.info("[G12-AjustarTributos] Total tributos formulario: " + Object.keys(tributosFormulario).length);

    if (Object.keys(tributosFormulario).length === 0) {
        log.warn("[G12-AjustarTributos] Nenhum tributo encontrado. Abortando.");
        return;
    }

    function formatarParaRM(valor) {
        return String(valor).replace(".", ",");
    }

    try {
        var servico   = ServiceManager.getService("wsDataServer");
        var instancia = servico.instantiate("com.totvs.WsDataServer");
        var ws        = instancia.getRMIwsDataServer();

        var properties = {};
        properties['basic.authorization']          = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking']             = 'true';
        properties['log.soap.messages']            = 'true';
        properties['receive.timeout']              = '180000';

        var authService = servico.getCustomClient(ws, properties, []);
        var contexto    = "CODCOLIGADA=" + codColigada + ";CODFILIAL=" + codFilial + ";CODSISTEMA=T;CODUSUARIO=fluig";

        log.info("[G12-AjustarTributos] Fazendo ReadRecord...");
        var xmlAtual = authService.readRecord("MovMovimentoTBCData", codColigada + ";" + idmov, contexto);
        log.info("[G12-AjustarTributos] ReadRecord OK");

        var xmlStr      = String(xmlAtual);
        var xmlTributos = "";

        function extrair(tag, texto) {
            var r = new RegExp("<" + tag + ">([^<]*)<\\/" + tag + ">");
            var m = r.exec(texto);
            return m ? m[1].trim() : "";
        }

        var regexBloco = /<TTRBITMMOV>([\s\S]*?)<\/TTRBITMMOV>/g;
        var match;

        while ((match = regexBloco.exec(xmlStr)) !== null) {
            var bloco = match[1];

            var codtrb      = extrair("CODTRB",           bloco);
            var basecalculo = extrair("BASEDECALCULO",    bloco);
            var aliquota    = extrair("ALIQUOTA",         bloco);
            var valor       = extrair("VALOR",            bloco);
            var editado     = extrair("EDITADO",          bloco) || "0";
            var tiporecolh  = extrair("TIPORECOLHIMENTO", bloco);
            var extras      = tiporecolh ? "<TIPORECOLHIMENTO>" + tiporecolh + "</TIPORECOLHIMENTO>" : "";

            log.info("[G12-AjustarTributos] Tributo lido: " + codtrb + " base=" + basecalculo + " aliq=" + aliquota + " valor=" + valor);

            if (tributosFormulario[codtrb]) {
                basecalculo = tributosFormulario[codtrb].basecalculo;
                aliquota    = tributosFormulario[codtrb].aliquota;
                valor       = tributosFormulario[codtrb].valor;
                editado     = "1";
                log.info("[G12-AjustarTributos] Atualizando tributo: " + codtrb);
            }

            xmlTributos +=
                "<TTRBITMMOV>" +
                    "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
                    "<IDMOV>"       + idmov       + "</IDMOV>" +
                    "<NSEQITMMOV>1</NSEQITMMOV>" +
                    "<CODTRB>"        + codtrb                      + "</CODTRB>" +
                    "<BASEDECALCULO>" + formatarParaRM(basecalculo) + "</BASEDECALCULO>" +
                    "<ALIQUOTA>"      + formatarParaRM(aliquota)    + "</ALIQUOTA>" +
                    "<VALOR>"         + formatarParaRM(valor)       + "</VALOR>" +
                    "<EDITADO>"       + editado                     + "</EDITADO>" +
                    extras +
                "</TTRBITMMOV>";
        }

        log.info("[G12-AjustarTributos] xmlTributos montado: " + xmlTributos);

        var xmlFinal =
            "<MovMovimento>" +
                "<TMOV>" +
                    "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
                    "<IDMOV>"       + idmov       + "</IDMOV>" +
                    "<INTEGRAAPLICACAO>T</INTEGRAAPLICACAO>" +
                "</TMOV>" +
                xmlTributos +
            "</MovMovimento>";

        var resultado = authService.saveRecord("MovMovimentoTBCData", xmlFinal, contexto);
        log.info("[G12-AjustarTributos] Resultado SaveRecord: " + resultado);

    } catch (e) {
        log.error("[G12-AjustarTributos] Erro: " + String(e));
        throw e;
    }
}

function getConstante(param) {
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

function servicetask30(attempt, message) {
	try {
		Cancelamento();
	} catch (e) {
		throw "servicetask30 " + e;
	}
}

function Cancelamento() {
	try {
		var usuario = getAccess()[0];
		var pass = getAccess()[1];
		var senha = new java.lang.String(pass);

		log.info("USUARIO LOGADO PARA CANCELAMENTO - > " + usuario)
		log.info("SENHA LOGADA PARA CANCELAMENTO - > " + senha)

		var codColigada = hAPI.getCardValue("CodColigada");
		var idMov = hAPI.getCardValue("IdMov");
		var numeroMov = hAPI.getCardValue("numeroMov");

		log.info("========== G12 servicetask30 - INICIO ==========");
		log.info(">> codColigada : [" + codColigada + "]");
		log.info(">> idMov       : [" + idMov + "]");
		log.info(">> numeroMov   : [" + numeroMov + "]");
		log.info(">> usuario     : [" + usuario + "]");

		var hoje = new java.text.SimpleDateFormat("dd/MM/yyyy")
			.format(new java.util.Date());


		var XML = "<MovCancelMovProcParams>";
		XML += "<MovimentosACancelar>";
		XML += "<MovimentosCancelar>";
		XML += "<ApagarMovRelac>false</ApagarMovRelac>";
		XML += "<CancelarMovimentosGeradosSimultFaturamento>false</CancelarMovimentosGeradosSimultFaturamento>";
		XML += "<CancelarMovimentosGeradosSimultReabriCotacao>false</CancelarMovimentosGeradosSimultReabriCotacao>";
		XML += "<CodColigada>" + codColigada + "</CodColigada>";
		XML += "<CodSistemaLogado>T</CodSistemaLogado>";
		XML += "<CodUsuarioLogado>fluig</CodUsuarioLogado>";
		XML += ValidaCampo("DataCancelamento", hoje);
		XML += "<ExcluirItensDaCotacao>false</ExcluirItensDaCotacao>";
		XML += ValidaCampo("IdMov", idMov);
		XML += ValidaCampo("MotivoCancelamento", "Movimento Cancelado por WorkFlow Fluig");
		XML += ValidaCampo("NumeroMov", numeroMov);
		XML += "</MovimentosCancelar>";
		XML += "</MovimentosACancelar>";
		XML += "</MovCancelMovProcParams>";

		log.info(">> XML enviado : [" + XML + "]");

		var NOME_SERVICO = "wsProcess";
		var CAMINHO_SERVICO = "com.totvs.WsProcess";
		var servico = ServiceManager.getServiceInstance(NOME_SERVICO);
		var serviceHelper = servico.getBean();
		var instancia = servico.instantiate(CAMINHO_SERVICO);
		var ws = instancia.getRMIwsProcess();
		var authenticatedService = serviceHelper.getBasicAuthenticatedClient(ws, "com.totvs.IwsProcess", usuario, senha);

		log.info(">> Chamando RM - MovCancelMovProc...");
		var response = authenticatedService.executeWithParams("MovCancelMovProc", XML);
		log.info(">> Response RM completo : [" + response + "]");


		log.warn("TIPO RESPONSE: " + typeof response);
		log.warn("RESPONSE RAW: " + response);

		if (response != null && (
			response.indexOf("===") != -1 ||
			response.indexOf("System.Exception") != -1 ||
			response.indexOf("Exception") != -1 ||
			response.indexOf("erro") != -1 ||
			response.indexOf("Erro") != -1
		)) {
			log.error(">> ERRO do RM detectado: [" + response + "]");
			throw "Erro RM: " + response;
		}


		log.info(">> Cancelamento executado com sucesso");
		log.info("========== G12 servicetask30 - FIM ==========");

		var dataset = DatasetBuilder.newDataset();
		dataset.addColumn("result");
		dataset.addRow(new Array(response));
		return dataset;

	} catch (e) {
		log.error(">> EXCECAO: [" + e.toString() + "]");
		return getDatasetError("ERRO:" + e.toString());
	}
}

function ValidaCampo(campo, valor) {
	if ((valor != null) && (valor != "")) {
		return "<" + campo + ">" + valor + "</" + campo + ">";
	} else {
		log.warn(">> Campo [" + campo + "] vazio - ignorado no XML");
		return "";
	}
}

function getAccess() {
	try {
		var response = new Array();
		var dataset = DatasetFactory.getDataset("dsTBCConnector", null, null, null);
		var u = dataset.getValue(0, "user");
		var p = dataset.getValue(0, "pass");
		log.info(">> getAccess: usuario [" + u + "]");
		response.push(u, p);
		return response;
	} catch (e) {
		throw "getAccess / " + e.toString();
	}
}

function getDatasetError(exception) {
	var dtsError = DatasetBuilder.newDataset();
	dtsError.addColumn("ERROR");
	dtsError.addRow([exception.toString()]);
	return dtsError;
}

function servicetask71(attempt, message) {
    /**
     * AUTHOR: ENOS DESENVOLVEDOR FLUIG/FULL STACK 
     * CRIADO EM: 29/05/2026
     * PROPOSITO: FATURAR OS MOVIMENTOS DE VENDAS DO TIPO 2.1.01 , CRIAR MOVIMENTO 2.1.02 E GERAR O RELACIONAMENTO ENTRE ELES DENTRO DO RM 
     * PUXAR OS DADOS DE TRIBUTACAO DO MOVIMENTO 2.1.02 PARA ATUALIZAR DENTRO DA TAELA DE IMPOSTOS DO FORMULARIO
    */



    var codColigada = hAPI.getCardValue("CodColigada");
    var idMov = hAPI.getCardValue("IdMov");
    var idmovMovimento02;
    var codFilial = hAPI.getCardValue("filial");
    var today = new java.text.SimpleDateFormat("yyyy-MM-dd").format(new java.util.Date());

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");



    try {

        /* 
        AQUI VAI ACONTECER A MÁGICA DA INTEGRACAO 
        1 - ServiceManager.getService("wsProcess")- > PRIMEIRO É NECESSÁRIO PEGAR O SERVICO QUE SERA RESPONSAVEL PELA INTEGRACAO DENTRO DO SEU FLUIG , EM PAIENL DE CONTROLE - SERVICOS 
        2 - instantiate() - > O SERVICO RESPOSAVEL POR INTEGRACOES MAIS COMPLEXAS DENTRO DO FLUIG É O WSPROCESS, TAMBÉM EXISTE O WSDATASERVER POREM ELE SERVE PARA CRUD MAIS SIMPLES, ALTERAR, EXCLUIR MOVIMENTOS, REALIZAR UPDATES ETCC
            COMO NESSE CASO É UMA OPERAÇÃO COMPLEXA QUE ENVOLVE RELACIONAMENTOS, FATURAMENTO, GERAÇÃO , TRANSFERENCIA DE DADOS ENTRE OS MOVIMENTOS ETC.. O WSPROCESS EXECUTA ISSO PERFEITAMENTE. 
        3 - IRÁ INSTANCIAR ESSE SERVICO , FAZER UMA ESPÉCIA DE CÓPIA DA CLASSE WSPROCESS (servico.instantiate("com.totvs.WsProcess"))
        4 - getRMIwsProcess() -> TEM ACESSO AOS METODOS DA CLASSE INTANCIADA 
        5 - properties -> INFORMACOES PARA AUTORIZACAO DO USO DO SERVICO DENTRO DO SERVIDOR DO RM, PRINCIPALMENTE O USUARIO E SENHA 
            E, INDISCUTIVELMENTE, UM TIMEOUT BOM, POIS, ISSO PODE IMPEDIR A EXECUSAO DA ATIVIDADE.
        6- getCustomClient() - > PASSAR AS INFORMACOES DE AUTORIZACOES E OS METODOS DA CLASSE INTANCIADA 
        7- executeWithParams() - > Metodo para faturar movimentos , passando o server name e o corpo XML -> executeWithParams("MovFaturamentoProc", xmlParams)

        */
        var servico = ServiceManager.getService("wsProcess");
        var instancia = servico.instantiate("com.totvs.WsProcess");
        var ws = instancia.getRMIwsProcess();
        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);

        log.info("### Servico OK, executando faturamento IDMOV=" + idMov);

        var xmlParams =
            '<MovFaturamentoProcParams>' +
            '<movCopiaFatPar>' +
            '<CodColigada>' + codColigada + '</CodColigada>' +
            '<CodSistema>T</CodSistema>' +
            '<CodTmvDestino>2.1.02</CodTmvDestino>' +
            '<CodTmvOrigem>2.1.01</CodTmvOrigem>' +
            '<CodUsuario>fluig</CodUsuario>' +
            '<GrupoFaturamento></GrupoFaturamento>' +
            '<IdExercicioFiscal>3</IdExercicioFiscal>' +
            '<IdMov>' +
            '<int>' + idMov + '</int>' +
            '</IdMov>' +
            '<TipoFaturamento>0</TipoFaturamento>' +
            '<dataBase>' + today + '</dataBase>' +
            '<dataEmissao/>' +
            '<dataSaida/>' +
            '<efeitoPedidoFatAutomatico>1</efeitoPedidoFatAutomatico>' +
            '<listaMovItemFatAutomatico/>' +
            '<numeroMov></numeroMov>' +
            '<realizaBaixaPedido>true</realizaBaixaPedido>' +
            '</movCopiaFatPar>' +
            '</MovFaturamentoProcParams>';

        var resp = authService.executeWithParams("MovFaturamentoProc", xmlParams);


    } catch (e) {
        log.error("### Erro: " + e);
        throw e;
    }


    // PARTE RESPONSAVEL POR ATUALIZAR OS DADOS DE TRIBUTACAO APOS SAI DA VALIDACAO DE CONTRATOS 
    try {
        var c2 = DatasetFactory.createConstraint("IDMOV", idMov, idMov, ConstraintType.MUST);

        var dataset = DatasetFactory.getDataset("G12-MOVIMENTOS-2102", null, [c2], null);


        if (dataset == null || dataset.rowsCount == 0) {
            log.warn("[G12] Nenhum movimento retornado." + "IdMov=" + idMov);
            return;
        }

        hAPI.setCardValue('idmov2', safe(dataset.getValue(0, "IDMOV")));
        var idmovMovimento02 = safe(dataset.getValue(0, "IDMOV"));





    } catch (error) {
        log.error("### Erro ao carregar movimento 2.1.02 no dataset - > : " + error);
        throw error;

    }

    // BUSCA OS IMPOSTOS DO MOVIMENTO 2.1.02 APOS A ATUALIZACAO DO FATURAMENTO DO 2.1.01 E SEU FATUTRAMENTO, COM A GERACAO DO 2.1.02


    try {
        var c1 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);
        var c2 = DatasetFactory.createConstraint("IDMOV", idmovMovimento02, idmovMovimento02, ConstraintType.MUST);

        var dataset = DatasetFactory.getDataset("G12-CARREGAR-TRIBUTOS", null, [c1, c2], null);


        if (dataset == null || dataset.rowsCount == 0) {
            log.warn("[G12] Nenhum tributo retornado. CodColigada=" + codColigada + " IdMov2=" + idmovMovimento02);
            return;
        }


        hAPI.setCardValue('tributosNacionais', safe(dataset.getValue(0, "TRIBUTOS_NACIONAIS")));
        hAPI.setCardValue('naturezaOrcamentaria', safe(dataset.getValue(0, "NATUREZA_ORCAMENTARIA")));
        hAPI.setCardValue('irrfDoItem', safe(dataset.getValue(0, "IRRF_DO_ITEM")));
        hAPI.setCardValue('inssDoItem', safe(dataset.getValue(0, "INSS_DO_ITEM")));
        hAPI.setCardValue('tributosMunicipais', safe(dataset.getValue(0, "TRIBUTOS_MUNICIPAIS")));


    } catch (e) {
        log.error("### Erro ao carregar impostos nacionais e municipias do dataset ->  " + e);
        throw e;
    }




}


function getConstante(param) {
    var aConstraint = [];
    aConstraint.push(DatasetFactory.createConstraint('id', param, param, ConstraintType.MUST));
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

function safe(valor) {
    log.info("VALOR DO IDMOV QUE ENTROU DENTRO DO CAMPO DE VALIDACAO DE CARREGAMENTO" + valor)
    if (valor == null || valor == undefined) return "";
    var s = String(valor).trim();
    return (s == "null" || s == "undefined") ? "" : s;
}

function servicetask9(attempt, message) {

    /***********************************************************************************************
 * @author      ENOS ROCHA - PROGRAMADOR FULL STACK
 * @data        18/05/2026
 * @Versao RM   12.1.2302.160
 * @Descricao   Carrega dados do contrato G12 via dataset G12-CARREGAR-DADOS
 *              e popula os campos do formulário via hAPI.setCardValue
 ***********************************************************************************************/

    try {
        // Nomes EXATOS que o RM envia — confirmados no log
        var codColigada = String(hAPI.getCardValue('CodColigada'));
        var idMov = String(hAPI.getCardValue('IdMov'));

        // hAPI.setCardValue("IdMov", idMov);

        log.info("[G12] CodColigada: " + codColigada);
        log.info("[G12] IdMov: " + idMov);

        loadDsG12(codColigada, idMov);

    } catch (e) {
        throw "Erro servicetask_g12: " + String(e) + " - Linha " + e.lineNumber;
    }
}

function loadDsG12(codColigada, idMov) {
    try {
        var c1 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);
        var c2 = DatasetFactory.createConstraint("IDMOV", idMov, idMov, ConstraintType.MUST);

        var dataset = DatasetFactory.getDataset("G12-CARREGAR-DADOS", null, [c1, c2], null);

        if (dataset == null || dataset.rowsCount == 0) {
            log.warn("[G12] Nenhum dado retornado. CodColigada=" + codColigada + " IdMov=" + idMov);
            return;
        }

        // Seção 1 — Identificação e Endereço do Projeto
        log.info("VALOR DO IDMOV -> " + dataset.getValue(0, "IDMOV"));
        hAPI.setCardValue('IDMOV_numero',            safe(dataset.getValue(0, "IDMOV")));
        hAPI.setCardValue('NumeroMov',               safe(dataset.getValue(0, "NUMERO_MOVIMENTO")));
        hAPI.setCardValue('coligada',                safe(dataset.getValue(0, "COLIGADA")));
        hAPI.setCardValue('filial',                  safe(dataset.getValue(0, "FILIAL")));
        hAPI.setCardValue('idprj',                   safe(dataset.getValue(0, "IDPRJ")));
        hAPI.setCardValue('cnpj',                    safe(dataset.getValue(0, "CNPJ_EMPRESA")));
        hAPI.setCardValue('cnpjCliente',             safe(dataset.getValue(0, "CNPJ_CLIENTE")));
        hAPI.setCardValue('centro_de_custo',         safe(dataset.getValue(0, "CENTRO_DE_CUSTO")));
        hAPI.setCardValue('codigo_do_projeto',       safe(dataset.getValue(0, "CODIGO_DO_PROJETO")));
        hAPI.setCardValue('descricao_projeto',       safe(dataset.getValue(0, "DESCRICAO_PROJETO")));
        hAPI.setCardValue('rua_projeto',             safe(dataset.getValue(0, "RUA_PROJETO")));
        hAPI.setCardValue('estado_projeto',          safe(dataset.getValue(0, "ESTADO_PROJETO")));
        hAPI.setCardValue('cidade_projeto',          safe(dataset.getValue(0, "CIDADE_PROJETO")));
        hAPI.setCardValue('complemento_projeto',     safe(dataset.getValue(0, "COMPLEMENTO_PROJETO")));
        hAPI.setCardValue('bairro_projeto',          safe(dataset.getValue(0, "BAIRRO_PROJETO")));
        hAPI.setCardValue('numero_endereco_projeto', safe(dataset.getValue(0, "NUMERO_ENDERECO_PROJETO")));
        
        hAPI.setCardValue('unidade_produto', safe(dataset.getValue(0, "UNIDADE_ITEM")));
        hAPI.setCardValue('quantidade_produto', safe(dataset.getValue(0, "QUANTIDADE_ITEM")));

        hAPI.setCardValue('cno', safe(dataset.getValue(0, "CNO")));
        hAPI.setCardValue('art', safe(dataset.getValue(0, "ART")));

        // Seção 2 — Detalhes do Contrato
        hAPI.setCardValue('numero_contrato',        safe(dataset.getValue(0, "NUMERO_CONTRATO")));
        hAPI.setCardValue('tipo_contrato',          safe(dataset.getValue(0, "TIPO_CONTRATO")));
        hAPI.setCardValue('numero_licitacao',       safe(dataset.getValue(0, "NUMERO_LICITACAO")));
        hAPI.setCardValue('codigo_cliente',         safe(dataset.getValue(0, "CODIGO_CLIENTE")));
        hAPI.setCardValue('data_contrato',          formatDate(safe(dataset.getValue(0, "DATA_CONTRATO"))));
        hAPI.setCardValue('data_inicio_contrato',   formatDate(safe(dataset.getValue(0, "DATA_INICIO_CONTRATO"))));
        hAPI.setCardValue('data_termino',           formatDate(safe(dataset.getValue(0, "DATA_TERMINO"))));
        hAPI.setCardValue('periodicidade_medicao',  safe(dataset.getValue(0, "PERIODICIDADE_MEDICAO")));
        hAPI.setCardValue('condicao_pagamento',     safe(dataset.getValue(0, "CONDICAO_PAGAMENTO")));
        hAPI.setCardValue('nome_produto',           safe(dataset.getValue(0, "NOME_PRODUTO")));
        hAPI.setCardValue('codigo_produto',         safe(dataset.getValue(0, "CODIGO_PRODUTO")));

        // Seção 3 — Prestador do Serviço (GFILIAL)
        hAPI.setCardValue('nomePrestador',              safe(dataset.getValue(0, "NOME_PRESTADOR")));
        hAPI.setCardValue('nomeEmpresarialPrestador',   safe(dataset.getValue(0, "NOME_PRESTADOR")));
        hAPI.setCardValue('incricaoPrestador',          safe(dataset.getValue(0, "INCRICAO_PRESTADOR")));
        hAPI.setCardValue('inscricaoMunicipalPrestador',safe(dataset.getValue(0, "INCRICAO_PRESTADOR")));
        hAPI.setCardValue('telefonePrestador',          safe(dataset.getValue(0, "TELEFONE_PRESTADOR")));
        hAPI.setCardValue('emailPrestador',             safe(dataset.getValue(0, "EMAIL_PRESTADOR")));
        hAPI.setCardValue('ruaPrestador',               safe(dataset.getValue(0, "RUA_PRESTADOR")));
        hAPI.setCardValue('numeroPrestador',            safe(dataset.getValue(0, "NUMERO_PRESTADOR")));
        hAPI.setCardValue('bairroPrestador',            safe(dataset.getValue(0, "BAIRRO_PRESTADOR")));
        hAPI.setCardValue('cidadePrestador',            safe(dataset.getValue(0, "CIDADE_PRESTADOR")));
        hAPI.setCardValue('estadoPrestador',            safe(dataset.getValue(0, "ESTADO_PRESTADOR")));
        hAPI.setCardValue('cepPrestador',               safe(dataset.getValue(0, "CEP_PRESTADOR")));
        hAPI.setCardValue('nome_filial',               safe(dataset.getValue(0, "NOME_FANTASIA")));

        // Campos compostos do prestador (usados pelo G12-NF-e.js)
        var endPrestador = joinNonEmpty([
            safe(dataset.getValue(0, "RUA_PRESTADOR")),
            safe(dataset.getValue(0, "NUMERO_PRESTADOR")),
            safe(dataset.getValue(0, "BAIRRO_PRESTADOR"))
        ], ", ");
        hAPI.setCardValue('enderecoPrestador',  endPrestador);
        hAPI.setCardValue('municipioPrestador', safe(dataset.getValue(0, "CIDADE_PRESTADOR")));

        // Seção 4 — Tomador do Serviço (FCFO)
        hAPI.setCardValue('incricaoTomador',  safe(dataset.getValue(0, "INSCRICAO_TOMADOR")));
        hAPI.setCardValue('telefoneTomador',  safe(dataset.getValue(0, "TELEFONE_TOMADOR")));
        hAPI.setCardValue('nomeEmpresarial',  safe(dataset.getValue(0, "NOME_TOMADOR")));
        hAPI.setCardValue('nome_cliente',  safe(dataset.getValue(0, "NOME_TOMADOR")));
        hAPI.setCardValue('emailTomador',     safe(dataset.getValue(0, "EMAIL_TOMADOR")));
        hAPI.setCardValue('ruaTomador',       safe(dataset.getValue(0, "RUA_TOMADOR")));
        hAPI.setCardValue('numeroTomador',    safe(dataset.getValue(0, "NUMERO_TOMADOR")));
        hAPI.setCardValue('bairroTomador',    safe(dataset.getValue(0, "BAIRRO_TOMADOR")));
        hAPI.setCardValue('cidadeTomador',    safe(dataset.getValue(0, "CIDADE_TOMADOR")));
        hAPI.setCardValue('cepTomador',       safe(dataset.getValue(0, "CEP_TOMADOR")));

        // Campos compostos do tomador (usados pelo G12-NF-e.js)
        var endTomador = joinNonEmpty([
            safe(dataset.getValue(0, "RUA_TOMADOR")),
            safe(dataset.getValue(0, "NUMERO_TOMADOR")),
            safe(dataset.getValue(0, "BAIRRO_TOMADOR"))
        ], ", ");
        hAPI.setCardValue('enderecoTomador',  endTomador);
        hAPI.setCardValue('municipioTomador', safe(dataset.getValue(0, "CIDADE_TOMADOR")));

        // Seção 5 — Local de Atuação IBS (TMOV)
        hAPI.setCardValue('codMuniIbs', safe(dataset.getValue(0, "COD_MUNI_IBS")));
        hAPI.setCardValue('codUfIbs',   safe(dataset.getValue(0, "COD_UF_IBS")));

        // Seção 6 — Item (TITMMOV)
        hAPI.setCardValue('unidadeItem',    safe(dataset.getValue(0, "UNIDADE_ITEM")));
        hAPI.setCardValue('quantidadeItem', safe(dataset.getValue(0, "QUANTIDADE_ITEM")));
        hAPI.setCardValue('valor_item', safe(dataset.getValue(0, "VALOR_ITEM")));

        // Seção 7 — Tributação
        // hAPI.setCardValue('tributosNacionais',   safe(dataset.getValue(0, "TRIBUTOS_NACIONAIS")));
        // hAPI.setCardValue('naturezaOrcamentaria',safe(dataset.getValue(0, "NATUREZA_ORCAMENTARIA")));
        // hAPI.setCardValue('irrfDoItem',          safe(dataset.getValue(0, "IRRF_DO_ITEM")));
        // hAPI.setCardValue('inssDoItem',          safe(dataset.getValue(0, "INSS_DO_ITEM")));
        // hAPI.setCardValue('tributosMunicipais',  safe(dataset.getValue(0, "TRIBUTOS_MUNICIPAIS")));

        // Seção 8 — Histórico (TMOVHISTORICO)
        hAPI.setCardValue('informacoesComplementaresNota', safe(dataset.getValue(0, "INFORMACOES_COMPLEMENTARES_NOTA")));
        hAPI.setCardValue('historicoMovimento', safe(dataset.getValue(0, "INFORMACOES_COMPLEMENTARES_NOTA")));

        log.info("[G12] Todos os campos preenchidos com sucesso para IdMov=" + idMov);

    } catch (e) {
        throw "Erro loadDsG12: " + String(e) + " - Linha " + e.lineNumber;
    }
}

function joinNonEmpty(parts, separator) {
    var result = [];
    for (var i = 0; i < parts.length; i++) {
        if (parts[i] && parts[i] !== "") result.push(parts[i]);
    }
    return result.join(separator);
}

function safe(valor) {
    log.info("VALOR DO IDMOV QUE ENTROU DENTRO DO CAMPO DE VALIDACAO DE CARREGAMENTO" + valor)
    if (valor == null || valor == undefined) return "";
    var s = String(valor).trim();
    return (s == "null" || s == "undefined") ? "" : s;
}

function formatDate(rawDate) {
    if (!rawDate || rawDate == "") return "";
    try {
        var inputFormat = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
        var outputFormat = new java.text.SimpleDateFormat("dd/MM/yyyy");
        return outputFormat.format(inputFormat.parse(rawDate));
    } catch (e) {
        return rawDate;
    }
}
